import{_ as a,o as n,c as o,a2 as i,j as e,a as r}from"./chunks/framework.Dkj3JE0_.js";const f=JSON.parse('{"title":"Environmental, Social, and Governance (ESG) Considerations in Investment Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/CFA/C4 Corporate Finance/M2 ESG.md","filePath":"blogs/CFA/C4 Corporate Finance/M2 ESG.md"}'),s={name:"blogs/CFA/C4 Corporate Finance/M2 ESG.md"},l={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},d={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.025ex"},xmlns:"http://www.w3.org/2000/svg",width:"2.262ex",height:"1.181ex",role:"img",focusable:"false",viewBox:"0 -511 1000 522","aria-hidden":"true"};function c(p,t,u,g,h,m){return n(),o("div",null,[t[13]||(t[13]=i('<h1 id="environmental-social-and-governance-esg-considerations-in-investment-analysis" tabindex="-1">Environmental, Social, and Governance (ESG) Considerations in Investment Analysis <a class="header-anchor" href="#environmental-social-and-governance-esg-considerations-in-investment-analysis" aria-label="Permalink to &quot;Environmental, Social, and Governance (ESG) Considerations in Investment Analysis&quot;">​</a></h1><p>This module covers how ownership structures shape corporate governance, how to evaluate a company&#39;s governance, and how to identify, evaluate and integrate ESG risks and opportunities into equity and credit analysis. Everything here is conceptual; there are no formulas to memorise.</p><ul><li><a href="#learning-outcomes-and-key-terms">Learning Outcomes and Key Terms</a>: what the module asks for, plus core vocabulary</li><li><a href="#ownership-structure">Ownership Structure</a>: dispersed vs concentrated, horizontal/vertical, dual-class, conflicts, influential shareholders, effects on governance</li><li><a href="#corporate-goverance-evaluation">Corporate Goverance Evaluation</a>: board policies and practices, remuneration, voting rights</li><li><a href="#esg">ESG</a>: materiality, horizon, relevant factors, three identification approaches, equity vs credit, green bonds</li><li><a href="#evaluating-esg-risks-and-opportunities">Evaluating ESG Risks and Opportunities</a>: ESG integration framework and the three textbook cases</li><li><a href="#quick-recall">Quick Recall</a>: one-line summary of each topic</li></ul><h2 id="learning-outcomes-and-key-terms" tabindex="-1">Learning Outcomes and Key Terms <a class="header-anchor" href="#learning-outcomes-and-key-terms" aria-label="Permalink to &quot;Learning Outcomes and Key Terms&quot;">​</a></h2><p>The candidate should be able to:</p><ul><li>Describe global variations in ownership structures and the possible effects of these variations on corporate governance policies and practices</li><li>Evaluate the effectiveness of a company&#39;s corporate governance policies and practices</li><li>Describe how ESG-related risk exposures and investment opportunities may be identified and evaluated</li><li>Evaluate ESG risk exposures and investment opportunities related to a company</li></ul><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Controlling shareholders</strong></td><td>An individual or group (family, other company/companies, sovereign) able to exercise control. Can be <strong>majority</strong> (&gt; 50%) <strong>or minority</strong> (&lt; 50%) holders</td></tr><tr><td><strong>Principal–agent problem</strong></td><td>Managers use company resources for their own interests instead of maximising shareholder value</td></tr><tr><td><strong>Principal–principal problem</strong></td><td>Controlling shareholders allocate resources to themselves at the expense of minority shareholders</td></tr><tr><td><strong>Voting caps</strong></td><td>Legal limits on the voting rights of large positions (often used by governments to deter foreign control of strategic companies)</td></tr><tr><td><strong>Interlocking directorates</strong></td><td>The same individuals sit on the boards of several corporations (common in Latin America)</td></tr><tr><td><strong>Insiders</strong></td><td>Managers and board directors who are also shareholders</td></tr><tr><td><strong>Shareholder activism</strong></td><td>Strategies shareholders use to try to compel a company to act in a desired manner</td></tr><tr><td><strong>ESG integration</strong></td><td>Implementing qualitative and quantitative ESG factors in traditional security and industry analysis <strong>and portfolio construction</strong></td></tr><tr><td><strong>Stranded assets</strong></td><td>Assets that are obsolete or not economically viable, often due to regulatory/policy changes or shifts in demand</td></tr><tr><td><strong>Greenwashing</strong></td><td>Risk that a green bond&#39;s proceeds are not actually used for a beneficial environmental/climate project</td></tr></tbody></table><h2 id="ownership-structure" tabindex="-1">Ownership Structure <a class="header-anchor" href="#ownership-structure" aria-label="Permalink to &quot;Ownership Structure&quot;">​</a></h2><ul><li>Dispersed ownership: many shareholders, none of which can individually exercise control</li><li>Concentrated ownership: an individual shareholder or a group (controlling shareholders) can exercise control</li><li>Hyprid ownership (In the middle)</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The textbook does <strong>not</strong> define dispersed/concentrated by fixed percentage cut-offs. The degree of share ownership alone may not show who controls the company: controlling shareholders can be <strong>majority (&gt; 50%) or minority (&lt; 50%)</strong> holders, because of horizontal/vertical arrangements and dual-class shares. (The only &quot;25%&quot; in the reading is the description of the UK, where few companies have holders owning 25% or more.)</p></div><p>Global picture (OECD 2017): <strong>38 of 47</strong> jurisdictions are predominantly concentrated.</p><table tabindex="0"><thead><tr><th>Classification</th><th>Jurisdictions</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Dispersed</strong></td><td>Australia, Ireland, UK, US</td><td>Australia: shares held (dispersed) mostly by financial institutions; US listed firms rarely controlled by a major holder</td></tr><tr><td><strong>Hybrid</strong></td><td>Canada, Germany, Japan, Netherlands, Switzerland</td><td>e.g. Germany: many under &quot;tight control&quot; but listed shares broadly distributed</td></tr><tr><td><strong>Concentrated</strong></td><td>The other 38 (e.g. China, France, India, Brazil, South Korea…)</td><td>State: China, Norway, Sweden. Families: Brazil, Mexico, Portugal, South Korea. Company groups: India, Russia</td></tr></tbody></table><p>Externally, there are structures as</p><ul><li>Horizontal ownership: Companies with mutual business interest (e.g. key customers or suppliers) that have cross-holding share arrangement with each other. Helps strategic alliances and long-term relationships.</li><li>Vertical ownership (pyramid ownership): A company or group that has a controlling interest in 2 or more holding companies, which in turn have controlling interests in various operating companies.</li></ul><p>Voting power:</p><p><strong>Dual-class shares</strong>: Grant one share class superior or even sole voting rights, where as other share classes has inferior or no voting rights. Combined with a pyramid, the group at the top can issue itself the superior-voting shares and control the operating companies while owning relatively few total shares.</p><h3 id="conflicts-within-different-ownership-structures" tabindex="-1">Conflicts within Different Ownership Structures <a class="header-anchor" href="#conflicts-within-different-ownership-structures" aria-label="Permalink to &quot;Conflicts within Different Ownership Structures&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ownership</th><th>Voting power</th><th>Shareholders vs managers</th><th>Main conflict</th></tr></thead><tbody><tr><td>Dispersed</td><td>Dispersed</td><td>Weak shareholders, <strong>strong managers</strong></td><td><strong>Principal–agent</strong></td></tr><tr><td>Concentrated</td><td>Concentrated</td><td><strong>Strong shareholders</strong>, weak managers</td><td><strong>Principal–principal</strong></td></tr><tr><td>Dispersed</td><td>Concentrated</td><td>Strong controlling holders <strong>without a majority</strong> of shares (via dual-class, pyramids)</td><td><strong>Principal–principal</strong></td></tr><tr><td>Concentrated</td><td>Dispersed</td><td>Arises from <strong>voting caps</strong></td><td>(Textbook gives the cause, not a named conflict)</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Controlling shareholders <strong>mitigate</strong> the principal–agent problem (they control the board, appoint managers, and have the incentive to monitor), but they <strong>create</strong> the principal–principal problem.</p></div><p><strong>Textbook example (Company A).</strong> Managers own ~30%; no other holder owns more than 1%; one share one vote. The textbook classifies this as dispersed ownership and dispersed voting power → weak shareholders, strong managers → <strong>principal–agent</strong> risk.</p><p>Types of influential Shareholders:</p><ul><li>Banks <ul><li>Common in Europe and Asia; lender <strong>and</strong> equity holder</li><li>Conflict: may push the company to take large loans, perhaps on less favorable terms, to the detriment of other shareholders</li></ul></li><li>Families <ul><li>Predominant in Latin America, and to a lesser extent Asia and Europe; often with interlocking directorates</li><li>Benefit: lower risks associated with principal-agent problems</li><li>Drawbacks: poor transparency, lack of management accountability, modest consideration for minority shareholder rights, and difficulty in attracting quality talent for management.</li></ul></li><li>State-owned enterprises (SOEs) <ul><li>Strategic sectors, capital needs beyond the private sector, or products the state wants at a set price/standard (e.g. power, health)</li><li>Listed SOE = <strong>mixed-ownership model</strong>: lower market scrutiny of management (implicit/explicit state guarantee against bankruptcy); may pursue social/public policy at the expense of shareholder value</li></ul></li><li>Institutioonal investors <ul><li>Mutual funds, pension funds, insurers, hedge funds; resources and expertise to use informed judgment</li><li>In dispersed markets usually <strong>not</strong> large enough to be controlling, but promote good governance by holding board/management accountable</li></ul></li><li>Group companies <ul><li>Horizontal/vertical structures → control disproportionate to ownership; cross-holdings restrict transfer of shares and block outsiders</li><li>Higher risk of <strong>related-party transactions</strong> against minority holders (e.g. Samsung, Sanwa, Grupo Carso)</li></ul></li><li>Private equity firms <ul><li>Venture capital (early stage, oversight) and LBO firms (majority control of mature companies)</li><li>May bring corporate codes and performance-based manager pay</li></ul></li><li>Foreign investors <ul><li>Influential in emerging markets when they own more than domestic investors; from stricter jurisdictions may demand more transparency</li><li>Cross-listing in a stricter market can benefit local minority holders</li></ul></li><li>Managers and board directors (insiders) <ul><li>Larger stakes → better alignment, more focus on long-term profitability</li><li>But large stakes can also give power to protect their own interests at others&#39; expense</li></ul></li></ul><p>Effects of Ownership Structure on Corporate Goverance</p><ul><li>Independent board directors: <ul><li>No material relationship with company (employment, ownership or remuneration)</li><li>Higher share of independent directors in dispersed jurisdictions (they originated there to strengthen monitoring of managers); share rose after scandals (e.g. Enron)</li><li>U.S. requires audit, nomination, and compensation committees be composed entirely of independent directors.</li><li>In most concentrated jurisdictions, nomination and remuneration committees are <strong>not mandatory</strong>; independent directors play a narrower role</li><li>OECD countries require/recommend either a minimum number (typically 1–3) or a minimum ratio (typically 20% to 50%+)</li></ul></li><li>Board Structure <ul><li>One-tier: Single board of directors, with executive (internal) and non-executive (external) directors. Most common</li><li>2-teir: Supervisory board that oversees a management board. Mandated in e.g. Argentina, Germany, Russia; optional in Brazil and France. Supervisory board inspects books, reviews annual report, oversees external auditors, sets/influences management pay; in Germany includes stakeholder representatives (banks, labor)</li></ul></li><li>Special voting arrangement <ul><li>Help minority holders take part in board nomination/election (e.g. Brazil, India, Portugal, Turkey, Italy, Israel, UK)</li><li>UK premium listing with a controlling holder: independent directors must be approved by <strong>both</strong> all shareholders <strong>and</strong> non-controlling shareholders</li></ul></li><li>Corporate governance codes, laws, and listing requirements <ul><li>National codes: <strong>&quot;comply or explain&quot;</strong>. Japan goes further: a company with no outside directors must justify why appointing them is not appropriate</li><li>Without a national code: company law/regulation (e.g. Chile) or exchange listing rules (e.g. India)</li></ul></li><li>Steward code <ul><li>Stewardship codes: (mostly voluntary) codes encouraging investors to exercise their rights and engage. UK Stewardship Code: institutional investors must monitor investees; UK asset managers must publish a &quot;comply or explain&quot; statement</li></ul></li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The principal–agent problem is generally <strong>less</strong> of a concern under concentrated ownership than under dispersed ownership, which is why independent directors play a narrower role there.</p></div><h2 id="corporate-goverance-evaluation" tabindex="-1">Corporate Goverance Evaluation <a class="header-anchor" href="#corporate-goverance-evaluation" aria-label="Permalink to &quot;Corporate Goverance Evaluation&quot;">​</a></h2><p>Effective governance may bring higher profitability, ROE growth, better access to credit, higher and sustainable dividends, good long-term share performance and a <strong>lower cost of capital</strong>. Ineffective governance: reputational damage, lower competitiveness, share price weakness/volatility, lower profitability, <strong>higher cost of capital</strong>.</p><ul><li>Governance factors are hard to quantify; start from disclosed policies, then dialogue/engagement; activism if needed</li><li>Also look at policies on business ethics, bribery and corruption, whistleblower protection and related-party transactions</li><li>In practice analysts reflect governance by adjusting the <strong>risk premium (cost of capital) or credit spread</strong></li></ul><h3 id="board-policies-and-practies" tabindex="-1">Board Policies and Practies <a class="header-anchor" href="#board-policies-and-practies" aria-label="Permalink to &quot;Board Policies and Practies&quot;">​</a></h3>',29)),e("ul",null,[t[11]||(t[11]=i("<li>CEO duality: CEO also serves as chairperson of the board <ul><li>Concern: board&#39;s monitoring/oversight may be compromised. If the chair is not independent or roles are combined, a <strong>lead independent director</strong> may be appointed</li></ul></li><li>Board independence <ul><li>No independent directors, or only a minority, is a <strong>negative</strong>: management may act in a self-serving way → higher perceived risk</li></ul></li><li>Board committee: <ul><li>Audit, Goverance, Renuimeration, Nomination, Risk, Compliance</li><li>Check there are sufficiently independent committees on key concerns; non-independent or executive members raise conflicts on pay (remuneration), management selection (nomination) and reporting integrity (audit)</li></ul></li><li>Board skills and experience: A board director&#39;s tenure is considered long if it exceeds 10 years. <ul><li>Concentrated skills, or diverse skills unrelated to core operations, may both be insufficient. Resource/high-ESG-risk sectors: board members typically have environmental, climate or social expertise</li><li>Long tenure: <strong>+</strong> deep understanding of the business and of management&#39;s record; <strong>−</strong> may impair independence (too close to management) and resistance to change</li></ul></li><li>Board composition: Reflects the number and diversity of directors (professional, cultural, geographical background, gender, age, tenure) <ul><li>Too many members or too little diversity may govern less effectively</li></ul></li><li>Board evaluation: self-evaluation or external review; covers duties, leadership, structure (incl. committees), board–management interaction (culture); may be targeted to shareholders, regulators or other stakeholders</li>",6)),e("li",null,[t[10]||(t[10]=r("Executive Remuneration (compensation) ",-1)),e("ul",null,[t[4]||(t[4]=e("li",null,"Transparent",-1)),t[5]||(t[5]=e("li",null,"Incentive plan (short-term and long-term performance criteria)",-1)),t[6]||(t[6]=e("li",null,"Linkage with company strategy",-1)),t[7]||(t[7]=e("li",null,"Pay differential between CEO and average worker",-1)),t[8]||(t[8]=e("li",null,[r("Say-on-pay provision: "),e("strong",null,"shareholders"),r(" can vote and/or give feedback on remuneration")],-1)),t[9]||(t[9]=e("li",null,[r("Claw-back policy: company can "),e("strong",null,"recover previously paid"),r(" remuneration if events such as financial restatements, misconduct, breach of law or risk management deficiencies are uncovered")],-1)),e("li",null,[t[2]||(t[2]=r("Excessive remuneration (often CEO pay ÷ average-worker pay) ",-1)),e("mjx-container",l,[(n(),o("svg",d,[...t[0]||(t[0]=[e("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[e("g",{"data-mml-node":"math"},[e("g",{"data-mml-node":"mo"},[e("path",{"data-c":"2192",d:"M56 237T56 250T70 270H835Q719 357 692 493Q692 494 692 496T691 499Q691 511 708 511H711Q720 511 723 510T729 506T732 497T735 481T743 456Q765 389 816 336T935 261Q944 258 944 250Q944 244 939 241T915 231T877 212Q836 186 806 152T761 85T740 35T732 4Q730 -6 727 -8T711 -11Q691 -11 691 0Q691 7 696 25Q728 151 835 230H70Q56 237 56 250Z",style:{"stroke-width":"3"}})])])],-1)])])),t[1]||(t[1]=e("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[e("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[e("mo",{accent:"false",stretchy:"false"},"→")])],-1))]),t[3]||(t[3]=r(" use KPI to analysis: check whether incentives drive company value",-1))])])]),t[12]||(t[12]=e("li",null,[r("Voting rights "),e("ul",null,[e("li",null,"Straight voting: one share, one vote"),e("li",null,"Dual class: founders/management hold higher-vote shares than the public class → potential conflict with minority holders")])],-1))]),t[14]||(t[14]=i('<p><strong>Textbook example (Style, Italian clothing retailer).</strong> 11-member board; chair (Leila Donato) is not the CEO; 2 independent directors; 4 of the 6 non-independent directors are Donato family, each 20+ years on the board; 5 women, ages 35–75.</p><table tabindex="0"><thead><tr><th>Positive</th><th>Negative</th></tr></thead><tbody><tr><td>No CEO duality</td><td>Only 2 independent directors; family includes the chair</td></tr><tr><td>Age and gender diversity</td><td>Family tenure far exceeds the typical 10 years</td></tr></tbody></table><p><strong>Textbook example (Sumiyoshi Banking Group, Japan, vs domestic peers).</strong></p><table tabindex="0"><thead><tr><th>Factor</th><th>Peers</th><th>Sumiyoshi</th></tr></thead><tbody><tr><td>Board type / size</td><td>Two tier / 13</td><td>Two tier / 14</td></tr><tr><td>CEO duality</td><td>Yes</td><td>Yes</td></tr><tr><td>Independent chair</td><td>Yes</td><td><strong>No</strong></td></tr><tr><td>Board independence</td><td>47%</td><td><strong>36%</strong></td></tr><tr><td>Female directors</td><td>17%</td><td><strong>7%</strong></td></tr><tr><td>Long tenure (&gt; 10 yrs)</td><td>0%</td><td><strong>14%</strong></td></tr><tr><td>Committees</td><td>5 (incl. governance)</td><td>4 (no governance committee)</td></tr><tr><td>Non-exec with industry exec experience / independent directors</td><td>67%</td><td><strong>20%</strong></td></tr><tr><td>Incentive metrics disclosed</td><td>No</td><td>No</td></tr><tr><td>Say-on-pay</td><td>Yes</td><td><strong>No</strong></td></tr><tr><td>Ownership / voting</td><td>No single large holder; straight voting, no dual class</td><td>Same</td></tr></tbody></table><p>Sumiyoshi lags on board composition. The analyst also uses credit risk as a governance proxy: NPLs / total loans is <strong>50 bps above peers</strong> → may raise the <strong>equity risk premium</strong> and the <strong>credit spread</strong> relative to peers.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Exam trap: CEO duality alone is not the whole story. Separate CEO/chair is positive, but independence, tenure and family/insider dominance can still make the board weak (Style).</p></div><h2 id="esg" tabindex="-1">ESG <a class="header-anchor" href="#esg" aria-label="Permalink to &quot;ESG&quot;">​</a></h2><p>Main challenge: getting information that is <strong>relevant, comparable and decision-useful</strong>. ESG data come mostly from public filings and sustainability reports (may or may not be third-party assured); reporting is <strong>inconsistent</strong> and most ESG disclosure is <strong>voluntary</strong>, though disclosure has increased over time.</p><p><strong>Materiality</strong> refers to ESG-related issues that are expected to affect company&#39;s operations, financial performance and the valuation of its securities, not relating to positive or negative. Companies may label positive but immaterial ESG information &quot;material&quot;, while minimising or not reporting negative information investors would consider material. Also considering the investment horizon match</p><ul><li>Horizon matters especially for <strong>credit analysts</strong> (different bond maturities)</li><li>Impact horizon can shift from long term to short term (and back) after a regulation change or a controversy such as an oil spill</li><li>Textbook case: manufacturer facing stricter future environmental rules; short-horizon investor sees little near-term profit effect, long-horizon investor expects costly plant upgrades or fines</li></ul><p>Relevant factors by industry:</p><ul><li>Governance: reasonably consistent across companies (best practice varies regionally)</li><li>Environmental and social: <strong>no globally accepted best practice</strong>; relevance depends on industry <ul><li>Energy companies: more affected by <strong>environmental</strong> factors</li><li>Banks: more by <strong>social</strong> factors (data security, privacy, customer satisfaction)</li><li>Both: governance</li></ul></li></ul><p>Three approaches to identify ESG factors (usable alone or combined):</p><table tabindex="0"><thead><tr><th>Approach</th><th>What it is</th><th>Examples from the textbook</th></tr></thead><tbody><tr><td><strong>Proprietary methods</strong></td><td>Analyst/firm judgment and tools; research companies, news, industry groups, environmental groups, labor organisations, experts, government</td><td>Annual reports, sustainability reports, proxy reports, 10-K; CDL climate scenario disclosure</td></tr><tr><td><strong>ESG data providers</strong></td><td>Vendors turn public disclosures into ESG analyses, scores and rankings, often with subjective analyst assessment; industry-relative rankings</td><td>MSCI, Sustainalytics</td></tr><tr><td><strong>Not-for-profit initiatives and reporting frameworks</strong></td><td>Data, insights and tools on ESG issues</td><td>IIRC (standardised ESG disclosure framework), GRI (sustainability reporting standards by industry), SASB (uniform sustainability accounting standards; <strong>materiality maps</strong>), 2DII; Access to Nutrition Index</td></tr></tbody></table><p><strong>Textbook example (City Developments Limited, CDL).</strong> Climate scenario planning aligned with TCFD and IPCC, with 2030 scenarios for 2°C and 1.5°C warming.</p><table tabindex="0"><thead><tr><th>Type</th><th>Items</th></tr></thead><tbody><tr><td>Transition risks</td><td>T1 policy risk (carbon taxes, stricter building standards; high priority), T2 water security, T3 waste responsibility, T4 higher insurance premiums / uninsurable assets</td></tr><tr><td>Physical risk</td><td>P1 more frequent/severe floods and heatwaves → stranded assets</td></tr><tr><td>Opportunities</td><td>O1 consumer activism, O2 global shift to low-carbon growth (high priority), O3 green finance in Singapore</td></tr></tbody></table><p>Disclosures range from minimal to many pages → <strong>comparability problems</strong> for analysts.</p><p>GRI example (consumer durables and household and personal products): environmental topics such as materials sourcing, packaging, plastic and chemicals use, energy efficiency of products; social topics such as migrant workers, product safety, labeling, e-waste; other topics such as corporate governance (executive compensation, gender on governance bodies) and supplier screening.</p><p><strong>ESG Integration</strong> Implementation of qualitative and quantitative ESG factors in traditional security and industry analysis as well as portfolio construction:</p><ul><li>Identify potential opportunites and mitigate downside risk</li></ul><table tabindex="0"><thead><tr><th></th><th>Equity</th><th>Fixed income (credit)</th></tr></thead><tbody><tr><td>Purpose</td><td>Identify <strong>opportunities and</strong> mitigate downside risk</td><td>Mainly <strong>mitigate downside risk</strong> (bond redeems at par)</td></tr><tr><td>Techniques</td><td>Forecast financial metrics/ratios, adjust valuation inputs (e.g. <strong>discount rate</strong>), sensitivity/scenario analysis</td><td>Internal credit assessments, forecast ratios, relative credit ranking; relative value, <strong>spread</strong>, <strong>duration</strong>, sensitivity/scenario analysis</td></tr><tr><td>Textbook illustration</td><td>Hotel: raise operating cost forecast for high employee turnover. Snack food: <strong>lower</strong> discount rate for moving to a sustainable key ingredient</td><td>Toy company: lawsuits hit credit ratios, cash flow, liquidity; spreads may widen. Coal company: stranded-asset risk hurts <strong>10-year</strong> notes much more than <strong>1-year</strong> notes</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Identification process and integration techniques are reasonably similar for equity and credit, but <strong>material factors and implications differ</strong>, and the credit (and CDS) effect can differ by <strong>maturity</strong>.</p></div><p><strong>Green bonds</strong>:</p><ul><li>Bond with environmental or climate benefits: proceeds designated to fund specific green project(s)</li><li>First one: European Investment Bank&#39;s Climate Awareness Bond, <strong>2007</strong></li><li>Issuer decides on the &quot;green&quot; label, in close cooperation with the lead underwriter; must disclose eligibility criteria and use of proceeds; may commission independent reviews</li><li><strong>Green Bond Principles</strong> (2014, consortium of investment banks; voluntary; maintained by ICMA). Index providers, rating agencies and the Climate Bonds Initiative have their own methods; the European Commission is exploring specific criteria</li><li>Issuer: extra monitoring/reporting costs, but a more diversified investor base and potentially a new-issue premium</li><li>Forms: plain-vanilla corporates, project bonds, MBS/ABS, municipals (e.g. California&#39;s US$300 million 2014 GO green bond, backed by the General Fund like its other GO bonds)</li><li>Same credit ratings and valuations: same ratings and bondholder recourse as the issuer&#39;s conventional bonds (all else equal); analysis and valuation essentially the same because only use of proceeds differs</li><li>May command a premium and a tighter credit spread <strong>because of market demand</strong> (not because they are less risky)</li><li>Greenwashing risk: investor may overpay for the green feature or hold a bond that fails an environmental mandate</li><li>Liquidity risk: often bought by buy-and-hold investors</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Exam trap: a green bond&#39;s credit risk is the issuer&#39;s credit risk. A tighter spread reflects <strong>demand</strong>, not lower default risk.</p></div><h2 id="evaluating-esg-risks-and-opportunities" tabindex="-1">Evaluating ESG Risks and Opportunities <a class="header-anchor" href="#evaluating-esg-risks-and-opportunities" aria-label="Permalink to &quot;Evaluating ESG Risks and Opportunities&quot;">​</a></h2><p>ESG integration steps:</p><ol><li>Identify <strong>material</strong> qualitative and quantitative ESG factors for the company/industry</li><li>Evaluate them historically, on a forecast basis and relative to peers</li><li>Adjust financials and valuation</li></ol><table tabindex="0"><thead><tr><th>Where</th><th>Typical ESG adjustments</th></tr></thead><tbody><tr><td>Income statement / cash flow</td><td>Revenues, operating and non-operating costs, margins, earnings, capex</td></tr><tr><td>Balance sheet</td><td>Estimate of <strong>impaired assets</strong></td></tr><tr><td>Equity valuation</td><td>Cost of capital / <strong>discount rate</strong>, price multiple, terminal value</td></tr><tr><td>Bond valuation</td><td><strong>Credit spread</strong> or CDS</td></tr></tbody></table><p><strong>ESG Integration Framework</strong> (source: <em>Guidance and Case Studies for ESG Integration: Equities and Fixed Income</em>, 2018): research (qualitative and quantitative), security valuation (equities and fixed income), plus portfolio construction, asset allocation, scenario analysis and risk management.</p><p>The textbook&#39;s three integration cases (each focuses on the most relevant pillar; the concepts carry over to other industries):</p><table tabindex="0"><thead><tr><th>Case</th><th>Pillar</th><th>Key metric</th><th>Financial adjustment</th><th>Valuation effect</th></tr></thead><tbody><tr><td><strong>Frizzle Drinks</strong> (US beverages)</td><td>Environmental</td><td><strong>Water intensity</strong> = liters of water used per liter of product; normalised per US$1 million revenue for peer comparison</td><td>Fell 27% 2009–2021, target another 13% by 2025F. COGS/revenue 2022F 40% (peers 42%), cut by 1% for lower water use → higher gross margin</td><td>Higher forecast earnings → higher fair value of stock; better operating cash flow for bonds/CDS; check whether lower ESG risk is <strong>already in spreads</strong></td></tr><tr><td><strong>Well Pharma</strong> (European pharma)</td><td>Social</td><td><strong>Product quality</strong>: controversies, regulatory warning letters, recalls, fines, % plants certified (e.g. ISO 9001)</td><td>Worst peer record (15 warning letters, 5 quality controversies vs fewer at peers). Revenue −2% next year; COGS/revenue +1.3%; non-operating expenses +4.5% of operating income. Treatment depends on whether issues are <strong>recurring or non-recurring</strong></td><td>Hurts earnings and cash flow for shareholders <strong>and</strong> bondholders; possible impaired brand value</td></tr><tr><td><strong>Sumiyoshi</strong> (Japanese bank)</td><td>Governance</td><td>Board composition vs peers; <strong>NPLs / total loans</strong> as governance proxy</td><td>NPL ratio 50 bps above peers</td><td>Higher equity risk premium; wider credit spread</td></tr></tbody></table><p>Well Pharma, factor → financial impact:</p><table tabindex="0"><thead><tr><th>Factor</th><th>Financial impact</th></tr></thead><tbody><tr><td>Product quality controversies</td><td>Brand damage → lower sales</td></tr><tr><td>Regulatory warning letters</td><td>Higher compliance costs</td></tr><tr><td>Product recalls</td><td>Lost revenue; recall costs</td></tr><tr><td>Regulatory fines</td><td>Provisions for sales returns and litigation</td></tr><tr><td>Low quality-certification %</td><td>Higher risk of quality issues, recalls and costs</td></tr></tbody></table><h2 id="quick-recall" tabindex="-1">Quick Recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick Recall&quot;">​</a></h2><ul><li>Ownership: dispersed / concentrated / hybrid; concentrated is far more common (38 of 47 OECD-surveyed jurisdictions)</li><li>Control ≠ ownership: horizontal (cross-holdings), vertical (pyramid), dual-class shares</li><li>Dispersed + dispersed → principal–agent; concentrated control (with or without majority ownership) → principal–principal; concentrated ownership + dispersed votes → voting caps</li><li>Influential holders: banks, families, SOEs, institutions, group companies, PE, foreign investors, insiders</li><li>Governance effects: independent directors, one- vs two-tier boards, special voting, comply-or-explain codes, stewardship codes</li><li>Board evaluation: CEO duality, independence, committees, skills, tenure (&gt; 10 yrs = long), composition, evaluation process</li><li>Remuneration: transparency, incentives, strategy link, CEO/worker pay; say-on-pay (shareholders vote); clawback (recover paid pay)</li><li>Governance enters valuation via risk premium / credit spread</li><li>ESG data: voluntary, inconsistent, comparability problems; materiality = affects operations, financials, valuation; match investment horizon</li><li>Identify factors: proprietary, data providers (MSCI, Sustainalytics), not-for-profit frameworks (IIRC, GRI, SASB, 2DII)</li><li>Equity: opportunities + downside; credit: mainly downside; maturity matters</li><li>Green bonds: only use of proceeds differs; same rating; demand-driven premium; greenwashing and liquidity risk</li><li>Integration cases: Frizzle (E, water intensity), Well (S, product quality), Sumiyoshi (G, board + NPLs)</li></ul>',36))])}const v=a(s,[["render",c]]);export{f as __pageData,v as default};
